'use strict';
(() => {
  const SAVE_KEY = 'shadow-system-eternal-monarch-v1';
  const $ = (s, root = document) => root.querySelector(s);
  const $$ = (s, root = document) => [...root.querySelectorAll(s)];
  const templates = {
    regions: ['Ashen Frontier','Crimson Wastes','Glassgrave Basin','The Drowned Meridian','Hollow Star Expanse','Infinite Abyss'],
    enemies: ['Hollow Hound','Cinder Wraith','Rift Stalker','Gravebound Knight','Ash Tyrant','Null Devourer','Dread Apostle'],
    bosses: ['The Gatekeeper','Crowned Devourer','Warden of the Lost','The Red Exile','Abyssal Regent'],
    events: ['A ribbon of black light tears across the clouds. Something on the other side notices you.','The gate shudders. Dust rises in the shape of a kneeling figure, then vanishes.','A distant bell rings once. The echo seems to come from inside your chest.','Your shadow moves a fraction of a second before you do.','The air tastes of iron. A new path has opened where the old one ended.'],
    loot: ['Rift-forged Fang','Ashen Core','Hunter’s Mantle','Voidglass Shard','Monarch’s Token','Cracked Gate Sigil','Echoing Ring','Dusksteel Fragment']
  };
  const backgrounds = {
    'The Forgotten One': {Luck:2,Perception:1},
    'The Exiled Hunter': {Agility:2,Strength:1},
    'The Unknown Awakener': {Intelligence:2,Vitality:1}
  };
  const baseStats = {Strength:5,Agility:5,Vitality:5,Intelligence:5,Perception:5,Luck:5};
  let state = null, selectedBackground = 'The Forgotten One', toastTimer;
  const esc = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const rand = n => Math.floor(Math.random()*n);
  const pick = arr => arr[rand(arr.length)];
  const clamp = (n,min,max) => Math.max(min,Math.min(max,n));
  const xpNeeded = level => Math.floor(100 * Math.pow(level, 1.28));
  const rankFor = level => level < 5 ? 'F' : level < 10 ? 'E' : level < 20 ? 'D' : level < 35 ? 'C' : level < 55 ? 'B' : level < 80 ? 'A' : level < 120 ? 'S' : 'EX';
  const classFor = s => s.classPath[s.classPath.length-1];
  const maxHp = s => 80 + s.stats.Vitality * 8 + (s.level-1)*12;
  const maxMp = s => 30 + s.stats.Intelligence * 5 + (s.level-1)*5;
  const log = (message,type='info') => { sfx(type); state.feed.unshift({message,time:new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}),type}); state.feed=state.feed.slice(0,7); };
  function freshState(name,bg){
    const stats={...baseStats,...backgrounds[bg]};
    const seed=Math.floor(Math.random()*0xffffff).toString(16).padStart(6,'0').toUpperCase();
    return {name:name.trim()||'JOKERSKID',background:bg,level:1,xp:0,points:0,stats,classPath:['Awakener'],hp:80+stats.Vitality*8,mp:30+stats.Intelligence*5,currency:25,inventory:[{name:'Field Ration',type:'Consumable',qty:3,description:'Restores 35 HP. Useful in a pinch.'},{name:'Gate Fragment',type:'Material',qty:1,description:'A warm shard humming with dormant power.'}],army:[],skills:[],skillPoints:0,quests:[],completed:0,relations:{},guild:null,seed,cycle:1,regionIndex:0,room:0,location:'The Ashen Frontier',roomType:'entrance',combat:null,history:0,feed:[],admin:false,muted:false};
  }
  function save(){if(!state)return;try{localStorage.setItem(SAVE_KEY,JSON.stringify(state));$('#save-status').textContent='PROGRESS SAVED';setTimeout(()=>{if($('#save-status'))$('#save-status').textContent='LOCAL SAVE READY'},1500)}catch(e){$('#save-status').textContent='SAVE FAILED'}}
  function load(){try{const raw=localStorage.getItem(SAVE_KEY);if(!raw)return null;const s=JSON.parse(raw);if(!s||!s.name||!s.stats||!Array.isArray(s.inventory))return null;s.admin=false;s.combat=null;s.hp=clamp(s.hp,1,maxHp(s));s.mp=clamp(s.mp,0,maxMp(s));return s}catch{return null}}
  function showToast(message,type=''){const node=document.createElement('div');node.className=`toast ${type}`;node.textContent=message;$('#toast-region').append(node);setTimeout(()=>node.remove(),3200)}
  function sfx(type){if(!state||state.muted)return;try{const ctx=new(window.AudioContext||window.webkitAudioContext)();const osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='sine';osc.frequency.value=type==='good'?660:type==='warn'?180:420;gain.gain.setValueAtTime(.035,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.12);osc.connect(gain);gain.connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+.12);osc.onended=()=>ctx.close()}catch{}}
  function activateGame(){ $('#welcome-screen').hidden=true;$('#creation-screen').hidden=true;$('#game-screen').hidden=false;$('#hud').hidden=false;render(); }
  function begin(){selectedBackground='The Forgotten One';$('#player-name').value='JOKERSKID';$$('.background-card').forEach(x=>x.classList.toggle('selected',x.dataset.background===selectedBackground));$('#welcome-screen').hidden=true;$('#creation-screen').hidden=false;}
  function createCharacter(){const name=$('#player-name').value.trim().slice(0,20)||'JOKERSKID';state=freshState(name,selectedBackground);state.quests.push({id:'first-gate',title:'A Door in the Dark',description:'Cross the first gate and prove that your awakening was no accident.',progress:0,target:1,reward:40,kind:'explore',active:true});log('[SYSTEM INITIALIZED] Awakening confirmed. The first gate is waiting.','good');state.history=1;state.lastNarrative=`<p>The world ends in ash beneath a colorless sky. You wake at the edge of a broken gate, one hand pressed to a pulse of violet light beneath your skin. Beyond it, something breathes.</p><p><strong class="system-note">[SYSTEM INITIALIZED] ${esc(name)}, your awakening has been recorded. There is no return to who you were.</strong></p>`;save();activateGame()}
  function updateHud(){const s=state;$('#avatar-initial').textContent=s.name.charAt(0).toUpperCase();$('#hud-name').textContent=s.name.toUpperCase();$('#hud-level').textContent=String(s.level).padStart(2,'0');$('#hud-xp').textContent=`${s.xp} / ${xpNeeded(s.level)} XP`;$('#xp-fill').style.width=`${Math.min(100,s.xp/xpNeeded(s.level)*100)}%`;$('#hud-hp').textContent=`${Math.max(0,s.hp)} / ${maxHp(s)}`;$('#hp-fill').style.width=`${Math.max(0,s.hp)/maxHp(s)*100}%`;$('#hud-mp').textContent=`MP ${s.mp} / ${maxMp(s)}`;$('#mp-fill').style.width=`${s.mp/maxMp(s)*100}%`;$('#hud-class').textContent=classFor(s).toUpperCase();$('#hud-background').textContent=s.background.toUpperCase();$('#hud-shadows').textContent=String(s.army.length).padStart(2,'0');$('#hud-rank').textContent=s.army.length?`${s.army.length} BOUND · ${s.army.reduce((a,x)=>a+(x.rank==='General'?1:0),0)} GENERAL`:'NO RANK';$('#hud-currency').innerHTML=`${s.currency} <b>◈</b>`;$('#hud-location').textContent=s.location.toUpperCase();$('#points-badge').hidden=s.points<=0;$('#points-badge').textContent=s.points;$('#army-badge').textContent=s.army.length;$('#guild-status').textContent=s.guild||'UNAFFILIATED';$('#region-rank').textContent=`${rankFor(s.level)}-RANK REGION`;$('#day-count').textContent=`CYCLE ${String(s.cycle).padStart(3,'0')}`;$('#world-seed').textContent=s.seed;$('#scene-location').textContent=`${s.location.toUpperCase()} · ${s.roomType.toUpperCase()}`;$('#scene-time').textContent=`CYCLE ${String(s.cycle).padStart(3,'0')} · ROOM ${String(s.room+1).padStart(2,'0')}`;$('#scene-tag').textContent=`FIELD REPORT · ${String(s.history).padStart(3,'0')}`;$('#scene-weather').textContent=pick(['ASHFALL','RIFT STATIC','BLACK WIND','SILENT']);}
  function render(){if(!state)return;updateHud();if($('#journey-panel').hidden===false){$('#narrative').innerHTML=state.lastNarrative||'<p>The wind drags ash across the broken gate. The dark beyond it is waiting for your first decision.</p>';renderChoices()}renderFeed();renderQuestCard();save()}
  function renderFeed(){const feed=$('#event-feed');feed.innerHTML=state.feed.length?state.feed.map(f=>`<div class="feed-item ${f.type==='good'?'accent':''}"><small>${esc(f.time)} · SYSTEM</small><p>${esc(f.message)}</p></div>`).join(''):'<div class="feed-item"><small>NOW · SYSTEM</small><p>No disturbances detected. The silence will not last.</p></div>'}
  function currentQuest(){return state.quests.find(q=>q.active)}
  function renderQuestCard(){const q=currentQuest(),el=$('#active-quest-card');el.innerHTML=q?`<span class="quest-type">${esc(q.kind.toUpperCase())} DIRECTIVE</span><h4>${esc(q.title)}</h4><p>${esc(q.description)}</p><div class="quest-progress"><span>PROGRESS</span><span>${q.progress} / ${q.target}</span></div><div class="quest-track"><i style="width:${Math.min(100,q.progress/q.target*100)}%"></i></div>`:`<span class="quest-type">NO ACTIVE DIRECTIVE</span><h4>Awaiting signal</h4><p>Explore the frontier to uncover new work.</p>`}
  function actionChoices(){const s=state;if(s.combat)return [
    {title:'Strike',desc:`Deal ${attackDamage()} damage. A direct, efficient attack.`,icon:'01',fn:()=>combatAction('attack')},
    {title:'Use Shadow Skill',desc:s.skills.length?`Unleash ${s.skills[0]}. Costs ${skillCost()} MP.`:'Focus your awakening. Restore 8 MP and reveal a weakness.',icon:'02',fn:()=>combatAction('skill')},
    {title:'Guard & Observe',desc:'Brace for impact. Reduce the next hit and uncover enemy intent.',icon:'03',fn:()=>combatAction('guard')},
    {title:'Attempt to Escape',desc:'Retreat from combat. Your pride—and some potential loot—stay behind.',icon:'04',fn:()=>combatAction('flee')}
  ];
    const choices=[];
    if(s.roomType==='entrance'||s.roomType==='cleared'){
      choices.push({title:'Enter the Rift Dungeon',desc:`Descend into a procedurally generated ${rankFor(s.level)}-rank gate. Danger scales with you.`,fn:()=>enterDungeon()});
      choices.push({title:'Scout the frontier',desc:'Search the ruined outskirts for clues, supplies, or a wandering threat.',fn:()=>explore()});
      choices.push({title:s.army.length?'Command your shadows':'Inspect the gate runes',desc:s.army.length?'Send your legion to scout the next chamber.':'The violet marks may explain why the gate chose you.',fn:()=>s.army.length?scoutArmy():inspectRunes()});
      choices.push({title:'Rest at the waystation',desc:'Recover health and mana, then decide what kind of legend to become.',fn:()=>rest()});
    }else{
      choices.push({title:'Advance to the next chamber',desc:'Step deeper into the gate. The threat escalates with each room.',fn:()=>advanceRoom()});
      choices.push({title:'Search the chamber',desc:'Inspect the remains and walls for hidden caches or useful intel.',fn:()=>searchRoom()});
      choices.push({title:s.army.length?'Command your shadows to scout':'Listen to the gate',desc:s.army.length?'Send a shadow ahead to reveal what waits beyond.':'The dark hums with a voice almost like your own.',fn:()=>s.army.length?scoutArmy():listenGate()});
      choices.push({title:'Return to the frontier',desc:'Withdraw from the dungeon. Your cleared rooms and rewards are yours to keep.',fn:()=>returnFrontier()});
    }
    return choices;
  }
  function renderChoices(){const el=$('#choices');el.innerHTML=actionChoices().map((c,i)=>`<button class="choice-button" data-choice="${i}"><span class="choice-number">${String(i+1).padStart(2,'0')}</span><span class="choice-copy"><strong>${esc(c.title)}</strong><small>${esc(c.desc)}</small></span><span class="choice-arrow">↗</span></button>`).join('');$$('.choice-button',el).forEach((b,i)=>b.addEventListener('click',()=>actionChoices()[i].fn()))}
  function updateQuest(kind,amount=1){for(const q of state.quests){if(!q.active||q.kind!==kind)continue;q.progress=Math.min(q.target,q.progress+amount);if(q.progress>=q.target){q.active=false;state.completed++;state.currency+=q.reward;log(`[QUEST COMPLETE] ${q.title} · +${q.reward} essence`,'good');showToast(`[QUEST COMPLETE] ${q.title} · +${q.reward} ◈`,'good');const follow=questTemplates.find(x=>!state.quests.some(old=>old.id===x.id));if(follow)state.quests.push({...follow,progress:0,active:true});break}}}
  const questTemplates=[
    {id:'cull-three',title:'A Quieting of Teeth',description:'Defeat three creatures stalking the frontier.',progress:0,target:3,reward:90,kind:'kill',active:true},
    {id:'gate-depths',title:'Beneath the First Seal',description:'Clear three rooms in the rift dungeon.',progress:0,target:3,reward:120,kind:'room',active:true},
    {id:'bind-shadow',title:'A Second Pulse',description:'Claim your first shadow from an elite or boss.',progress:0,target:1,reward:140,kind:'extract',active:true},
    {id:'gather-cache',title:'Useful Remnants',description:'Find two caches in the wild or beyond the gate.',progress:0,target:2,reward:70,kind:'loot',active:true}
  ];

function setScene(paragraphs,choices=true){state.lastNarrative=paragraphs.map(p=>`<p>${p}</p>`).join('');if(choices)renderChoices();renderFeed();renderQuestCard();updateHud();save()}
function grantXp(amount){state.xp+=amount;let leveled=false;while(state.xp>=xpNeeded(state.level)){state.xp-=xpNeeded(state.level);state.level++;state.points+=3;state.skillPoints++;state.hp=maxHp(state);state.mp=maxMp(state);leveled=true;log(`[LEVEL UP] Level ${state.level}. +3 attribute points, +1 skill point.`,'good');showToast(`[LEVEL UP] Level ${state.level} · +3 stat points · +1 skill point`,'good');if(state.level===5||state.level===10||state.level===20||state.level===35)offerEvolution()}if(leveled)render();return leveled}
function offerEvolution(){const options=classFor(state)==='Awakener'?['Shadowbound','Rift Hunter','Void Arcanist']:classFor(state)==='Shadowbound'?['Shadow Sovereign']:[];if(!options.length)return;modal('CLASS EVOLUTION AVAILABLE',`Your power has outgrown its first shape. Choose a permanent path. Each choice changes the story—and the way you fight.`,options.map(name=>({label:name.toUpperCase(),action:()=>evolve(name)})).concat([{label:'DECIDE LATER',action:()=>{}}]))}
function evolve(name){state.classPath.push(name);state.stats[name==='Rift Hunter'?'Agility':name==='Void Arcanist'?'Intelligence':'Strength']+=2;log(`[CLASS EVOLUTION] You have become ${name}.`,'good');showToast(`[CLASS EVOLUTION] ${name}`,'good');setScene([`A new name writes itself across the inside of your vision: <strong>${esc(name)}</strong>. The old shape of your power cracks away.`,`<strong class="system-note">[CLASS EVOLUTION] ${esc(name)} · Permanent path recorded.</strong>`])}
function attackDamage(){return Math.max(8,Math.floor(state.stats.Strength*2+state.stats.Agility*.8+state.level*2+rand(8)))}
function skillCost(){return 10+Math.floor(state.level/5)}
function enemyPower(){return state.level*4+state.room*3+8}
function newEnemy(boss=false,elite=false){const scale=Math.max(1,state.level);return {name:boss?pick(templates.bosses):pick(templates.enemies),boss,elite:elite||boss,maxHp:Math.floor((boss?75:elite?48:30)+scale*(boss?27:elite?15:9)+state.room*8),hp:0,attack:Math.floor(6+scale*2.2+state.room*1.6),loot:pick(templates.loot)};}
function startCombat(enemy,origin='field') {enemy.hp=enemy.maxHp;state.combat={enemy,origin,guarding:false,turn:0,extractChance:enemy.boss?70:enemy.elite?45:0};log(`[THREAT DETECTED] ${enemy.name} · ${enemy.boss?'BOSS':enemy.elite?'ELITE':'HOSTILE'}`,'warn');const banner=`<div class="combat-banner"><div><strong>${esc(enemy.boss?'BOSS SIGNATURE':enemy.elite?'ELITE SIGNATURE':'HOSTILE CONTACT')} · ${esc(enemy.name.toUpperCase())}</strong><div class="enemy-meter"><i style="width:100%"></i></div></div><span>HP ${enemy.hp} / ${enemy.maxHp}</span></div>`;setScene([`The dark peels open. <strong>${esc(enemy.name)}</strong> steps through the seam, its silhouette edged in hungry violet light.`,`There is no room to run the gate. Your shadow stretches toward the thing as if it has been waiting.` ,banner]);renderChoices()}
function combatAction(action){const c=state.combat;if(!c)return;const e=c.enemy;c.turn++;let prose='';if(action==='attack'){const damage=attackDamage();e.hp=Math.max(0,e.hp-damage);prose=`You close the distance and strike. <strong>${esc(e.name)}</strong> takes ${damage} damage.`}
  if(action==='skill'){if(state.skills.length&&state.mp>=skillCost()){state.mp-=skillCost();const damage=Math.floor(attackDamage()*1.85+state.stats.Intelligence*2);e.hp=Math.max(0,e.hp-damage);prose=`Shadow energy folds around your arm. <strong>${esc(state.skills[0])}</strong> detonates for ${damage} damage.`}else if(state.mp<skillCost()&&state.skills.length){state.mp=Math.min(maxMp(state),state.mp+4);prose='Your mana is too low to shape a technique. You gather a faint trace of power instead, recovering 4 MP.'}else{state.mp=Math.min(maxMp(state),state.mp+8);prose=`You focus on the enemy's core. The gate reveals a seam in its armor; you recover 8 MP.`}}
  if(action==='guard'){c.guarding=true;prose=`You lower your center of gravity and study ${esc(e.name)}. Your guard will blunt the next hit.`}
  if(action==='flee'){if(c.origin==='field'||Math.random()<.58){state.combat=null;state.hp=Math.max(1,state.hp-Math.ceil(e.attack*.4));state.roomType=c.origin==='dungeon'?'cleared':'entrance';setScene([`You retreat through a fracture in space. <strong>${esc(e.name)}</strong> roars behind you as the gate seals.`,`You take a glancing blow on the way out, but live to choose another path.`]);log('You withdrew from combat.','warn');grantXp(8);return}else{prose='The gate rejects your retreat. The path folds back into the chamber.'}}
  if(e.hp<=0){winCombat(prose);return}
  let incoming=Math.max(1,e.attack+rand(7)-Math.floor(state.stats.Agility/5));if(c.guarding){incoming=Math.ceil(incoming*.35);c.guarding=false}if(state.army.length)incoming=Math.max(1,incoming-Math.min(8,state.army.reduce((n,x)=>n+(x.rank==='General'?4:x.rank==='Knight'?2:1),0)));state.hp-=incoming;
  if(state.hp<=0){state.hp=1;state.combat=null;state.currency=Math.max(0,state.currency-Math.floor(state.currency*.1));state.mp=Math.floor(state.mp*.4);state.roomType='cleared';state.location='The Ashen Frontier';log('[SYSTEM ALERT] Critical state. Emergency extraction engaged.','warn');showToast('[SYSTEM ALERT] Defeated · rescued to the frontier. Lost 10% essence.','warn');setScene([`${prose} <strong>${esc(e.name)}</strong> retaliates for ${incoming}. The world cuts to black.`,`You wake at the outer gate. The system dragged you back from the brink; your remaining essence was the price.`]);renderChoices();return}
  const newWidth=Math.max(0,e.hp/e.maxHp*100);const newBanner=`<div class="combat-banner"><div style="flex:1;margin-right:15px"><strong>${esc(e.boss?'BOSS SIGNATURE':e.elite?'ELITE SIGNATURE':'HOSTILE CONTACT')} · ${esc(e.name.toUpperCase())}</strong><div class="enemy-meter"><i style="width:${newWidth}%"></i></div></div><span>HP ${e.hp} / ${e.maxHp}</span></div>`;
  setScene([prose,`<strong>${esc(e.name)}</strong> lashes out for ${incoming} damage. ${state.army.length?'Your shadows absorb part of the blow.':''}`,newBanner]);
}
function winCombat(lastAction='') {const c=state.combat,e=c.enemy,origin=c.origin;state.combat=null;state.currency+=Math.floor(8+state.level*3+(e.boss?40:e.elite?20:0));state.hp=Math.min(maxHp(state),state.hp+Math.floor(e.maxHp*.08));state.mp=Math.min(maxMp(state),state.mp+Math.floor(e.maxHp*.05));const xp=Math.floor(25+state.level*11+(e.boss?100:e.elite?45:0));grantXp(xp);updateQuest('kill');const drops=[];if(Math.random()<.78||e.elite||e.boss){const loot={name:e.loot,type:'Material',qty:1,description:`Recovered from ${e.name}. Its value rises with the gate's rank.`};addItem(loot);drops.push(e.loot);updateQuest('loot')};if(Math.random()<.25){const potion={name:'Minor Elixir',type:'Consumable',qty:1,description:'Restores 45 HP and 20 MP.'};addItem(potion);drops.push('Minor Elixir')}
  if(origin==='dungeon'){state.roomType='cleared';state.room++;updateQuest('room')};log(`[VICTORY] ${e.name} defeated · +${xp} XP · +${Math.floor(8+state.level*3+(e.boss?40:e.elite?20:0))} essence`,'good');let text=[lastAction||'The creature collapses into ash.'];text.push(`<strong>${esc(e.name)}</strong> dissolves. You gain <strong>${xp} XP</strong> and reclaim a trace of strength. ${drops.length?`Recovered: ${drops.map(esc).join(', ')}.`:'No tangible loot remains.'}`);if(e.elite||e.boss){state.pendingExtraction={name:e.name,rank:e.boss?'Knight':'Elite',chance:c.extractChance};text.push(`<strong class="system-note">[SHADOW EXTRACTION AVAILABLE] ${c.extractChance}% chance. Choose “ARISE” in the next prompt—or type ARISE.</strong>`);log(`[SHADOW EXTRACTION AVAILABLE] ${c.extractChance}% success chance.`)}setScene(text);renderChoices();}
function addItem(item){const existing=state.inventory.find(x=>x.name===item.name);if(existing)existing.qty+=item.qty;else state.inventory.push(item)}
function extractShadow(){const p=state.pendingExtraction;if(!p){setScene(['<strong class="system-note">[SYSTEM] No defeated elite or boss is available for extraction.</strong>']);showToast('[SYSTEM] No shadow to extract.','warn');return}const success=Math.random()*100<p.chance;if(success){const shadow={name:p.name,rank:p.rank,level:state.level,loyalty:100};state.army.push(shadow);log(`[SHADOW EXTRACTION SUCCESSFUL] ${shadow.name} bound as ${shadow.rank}.`,'good');showToast(`[SHADOW EXTRACTION SUCCESSFUL] ${shadow.name} joins your legion.`,'good');state.pendingExtraction=null;setScene([`You speak the word: <strong>ARISE.</strong> The fallen creature's shadow tears free and kneels at your feet.`,`<strong class="system-note">[SHADOW EXTRACTION SUCCESSFUL] ${esc(shadow.name)} · ${shadow.rank} · Bound to your legion.</strong>`])}else{log('[SHADOW EXTRACTION FAILED] The essence disperses into the gate.','warn');showToast('[SHADOW EXTRACTION FAILED] The shadow resisted.','warn');state.pendingExtraction=null;setScene([`You reach into the fading darkness. It recoils, then scatters into sparks before your grasp can close.`,`<strong class="system-note">[EXTRACTION FAILED] The gate has consumed the remaining essence.</strong>`])}}
function enterDungeon(){state.location=`${pick(templates.regions)} · Gate ${String(state.cycle).padStart(3,'0')}`;state.room=0;state.roomType='dungeon';state.cycle++;state.combat=null;updateQuest('explore');const roll=Math.random();if(roll<.25)startCombat(newEnemy(false,true),'dungeon');else if(roll<.77)startCombat(newEnemy(false,false),'dungeon');else{state.roomType='treasure';setScene([`The gate swallows your light. You emerge in a corridor carved through black glass; distant shapes move behind the walls.`,`A sealed cache hums beneath a collapsed arch. Something heavy is pacing the chamber beyond it.`])}log(`[GATE ENTERED] ${state.location} · ${rankFor(state.level)} rank`,'info');}
function explore(){state.history++;const roll=Math.random();if(roll<.42){const elite=roll<.14;startCombat(newEnemy(false,elite),'field');return}if(roll<.7){const amount=Math.floor(10+state.level*4+rand(12));state.currency+=amount;const item={name:pick(templates.loot),type:'Material',qty:1,description:'Scavenged from the frontier. Its resonance shifts with your level.'};addItem(item);updateQuest('loot');grantXp(12+state.level*3);log(`[CACHE FOUND] +${amount} essence · ${item.name}`,'good');setScene([`You follow a trail of pale embers to a half-buried supply capsule. It opens at your touch, though no one remembers leaving it here.`,`Inside: <strong>${amount} essence</strong> and <strong>${esc(item.name)}</strong>. The capsule's locator flickers toward the nearest gate.`]);return}const event=pick(templates.events);grantXp(8+state.level*2);log('[FRONTIER EVENT] Unusual gate activity detected.');setScene([event,'The frontier is larger than it looked from the gate. The system records your movement and quietly recalibrates the danger ahead.']);}
function inspectRunes(){grantXp(8);const roll=Math.random();if(roll<.45){state.mp=Math.min(maxMp(state),state.mp+12);setScene(['The runes are not words but a record of choices made in another timeline. One glyph answers your pulse and spills warmth into your veins.','<strong class="system-note">[INSIGHT GAINED] +8 XP · +12 MP · The gate remembers you now.</strong>'])}else{state.stats.Perception+=1;setScene(['The runes shift under your gaze. You recognize a deliberate flaw in the seal—a door someone wanted you to find.','<strong class="system-note">[HIDDEN PATH REVEALED] +8 XP · +1 Perception (permanent).</strong>'])}}
function listenGate(){grantXp(10);if(Math.random()<.5){state.skillPoints++;setScene(['You place your palm against the glass. Behind it, countless versions of your heartbeat answer in unison.','<strong class="system-note">[AWAKENING RESONANCE] +10 XP · +1 skill point.</strong>'])}else setScene([`A voice like yours whispers a name from somewhere below. You remember nothing—but the sound leaves you sharper.`,`<strong class="system-note">[GATE INSIGHT] +10 XP · The next encounter is revealed by the gate.</strong>`])}
function rest(){const cost=10+state.level*2;if(state.currency<cost){setScene([`The waystation's keeper wants ${cost} essence to restore you. You only have ${state.currency}.`,'A dim brazier waits beside the door. It asks for more than a promise.']);return}state.currency-=cost;state.hp=maxHp(state);state.mp=maxMp(state);grantXp(5+state.level);log(`[REST] Vitality restored · −${cost} essence`,'good');setScene([`You rest beside the gatekeeper's violet brazier. Its flame burns without fuel, and the ache in your bones begins to loosen.`,`<strong class="system-note">[REST COMPLETE] HP and MP restored · −${cost} essence · +${5+state.level} XP.</strong>`])}
function advanceRoom(){state.roomType='dungeon';const r=Math.random();if(r<.16){state.roomType='boss';startCombat(newEnemy(true),'dungeon')}else if(r<.47){startCombat(newEnemy(false,true),'dungeon')}else if(r<.82){startCombat(newEnemy(false,false),'dungeon')}else{state.roomType='treasure';setScene([`The next chamber is a silent observatory. A cracked lens points at a star that does not exist in this sky.`,`A cache sits under the lens. A hair-thin pressure plate glimmers beneath the dust.`]);}}
function searchRoom(){const chance=state.stats.Perception*2+state.stats.Luck*2;if(Math.random()*100<Math.min(85,chance)){const item={name:pick(templates.loot),type:'Material',qty:1,description:'Hidden chamber salvage; the gate has marked it for your inventory.'};const amount=8+state.level*3+rand(15);addItem(item);state.currency+=amount;grantXp(10+state.level*2);updateQuest('loot');state.roomType='cleared';log(`[CACHE FOUND] ${item.name} · +${amount} essence`,'good');setScene([`Your eye catches the seam before your boot reaches the plate. Behind the wall: <strong>${esc(item.name)}</strong> and <strong>${amount} essence</strong>.`,`<strong class="system-note">[TRAP AVOIDED] Perception and luck turned the chamber's teeth against it.</strong>`])}else{const damage=Math.ceil((7+state.level*2)*(100/(100+state.stats.Agility*2)));state.hp=Math.max(1,state.hp-damage);state.roomType='cleared';grantXp(8);log(`[TRAP] Pressure sigil triggered · −${damage} HP`,'warn');setScene([`The pressure plate flares before you can move. A line of black fire cuts across the chamber; you take ${damage} damage and the sigil goes dark.`,`Whatever treasure was here is gone. The next room waits beyond the scorched arch.`])}}
function scoutArmy(){if(!state.army.length){inspectRunes();return}const scout=state.army[rand(state.army.length)];const danger=rand(100);grantXp(8+state.level);if(danger<28){const damage=5+state.level*2;state.hp=Math.max(1,state.hp-damage);scout.loyalty=Math.max(50,scout.loyalty-5);setScene([`<strong>${esc(scout.name)}</strong> slips into the dark and returns wounded. It has mapped the next chamber, but something struck from behind.`,`<strong class="system-note">[SCOUT REPORT] Threat ahead · You take ${damage} damage as the gate's backlash reaches you.</strong>`]);log(`${scout.name} returned injured from a scouting run.`,'warn')}else{const found=8+state.level*3+rand(12);state.currency+=found;setScene([`<strong>${esc(scout.name)}</strong> flows ahead as a smear of living night. It returns with a map of the next room and a fistful of warm essence.`,`<strong class="system-note">[SCOUT REPORT] Path revealed · +${found} essence · +${8+state.level} XP.</strong>`]);log(`${scout.name} scouted successfully · +${found} essence.`,'good')}}
function returnFrontier(){state.location='The Ashen Frontier';state.room=0;state.roomType='entrance';state.combat=null;state.hp=Math.max(1,state.hp);setScene(['The gate folds in on itself. For a moment, you see an ocean of doors stretching to the horizon.','The Ashen Frontier receives you without a word. The waystation brazier is still lit.']);log('[GATE EXITED] Progress and collected rewards retained.','info')}
function modal(title,body,buttons){const root=$('#modal-root');root.innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="system-label"><i></i> SYSTEM NOTIFICATION</div><h3>${esc(title)}</h3><p>${body}</p><div class="modal-actions">${buttons.map((b,i)=>`<button class="${i===0?'primary-button':'modal-close'}" data-modal-choice="${i}">${esc(b.label)}</button>`).join('')}</div></div></div>`;$$('[data-modal-choice]',root).forEach((el,i)=>el.addEventListener('click',()=>{root.innerHTML='';buttons[i].action()}));}
function openPanel(name){$$('.nav-item[data-panel]').forEach(x=>x.classList.toggle('active',x.dataset.panel===name));$('#journey-panel').hidden=name!=='journey';$('#secondary-panel').hidden=name==='journey';$('#view-title').textContent=name==='journey'?(state.combat?`Combat · ${state.combat.enemy.name}`:state.location):({character:'Character',skills:'Skill tree',inventory:'Inventory',army:'Shadow legion',quests:'Quest log',guild:'Guild hall',admin:'System administration'}[name]||'Journey');$('#breadcrumb').textContent=`${name==='journey'?'WORLD':'MONARCH INTERFACE'} / ${name.toUpperCase()}`;if(name==='journey'){renderChoices();return}$('#secondary-panel').innerHTML=panelContent(name);bindPanel(name);}
