  function bindPanel(name){$$('[data-attribute]').forEach(b=>b.onclick=()=>{const key=b.dataset.attribute;if(!state.points)return;state.stats[key]++;state.points--;if(key==='Vitality')state.hp+=8;if(key==='Intelligence')state.mp+=5;log(`[ATTRIBUTE INCREASED] ${key} is now ${state.stats[key]}.`,'good');openPanel('character');updateHud()});$$('[data-skill]').forEach(b=>b.onclick=()=>{const skill=b.dataset.skill;const need=skill==='Umbral Strike'?1:skill==='Monarch’s Guard'?3:skill==='Rift Step'?4:skill==='Army of One'?6:8;state.skills.push(skill);state.skillPoints-=need;log(`[TECHNIQUE UNLOCKED] ${skill}.`,'good');showToast(`[TECHNIQUE UNLOCKED] ${skill}`,'good');openPanel('skills')});$$('[data-use-item]').forEach(b=>b.onclick=()=>useItem(Number(b.dataset.useItem)));$$('[data-promote]').forEach(b=>b.onclick=()=>promote(Number(b.dataset.promote)));$$('[data-join-guild]').forEach(b=>b.onclick=()=>joinGuild(b.dataset.joinGuild));$$('[data-jump]').forEach(b=>b.onclick=()=>openPanel(b.dataset.jump));$$('[data-admin]').forEach(b=>b.onclick=()=>adminAction(b.dataset.admin));const scout=$('#army-scout');if(scout)scout.onclick=()=>{openPanel('journey');scoutArmy()};const drill=$('#army-drill');if(drill)drill.onclick=()=>{if(!state.army.length)return;const cost=15+state.level*2;if(state.currency<cost){showToast(`Need ${cost} essence to drill.`,'warn');return}state.currency-=cost;state.army.forEach(x=>x.loyalty=Math.min(100,x.loyalty+4));grantXp(10);log(`[LEGION DRILL] Loyalty increased · −${cost} essence`,'good');openPanel('army')};const contract=$('#guild-contract');if(contract)contract.onclick=()=>guildContract();$('#delete-save')?.addEventListener('click',()=>modal('RESET LOCAL SAVE?','This permanently erases your current character and all progress from this browser.',[{label:'RESET SAVE',action:()=>{localStorage.removeItem(SAVE_KEY);location.reload()}},{label:'CANCEL',action:()=>{}}]));}
  function useItem(i){const item=state.inventory[i];if(!item||item.type!=='Consumable')return;if(item.name==='Field Ration'){const amount=Math.min(35,maxHp(state)-state.hp);state.hp+=amount;showToast(`[ITEM USED] Field Ration · +${amount} HP`,'good')}else{const hp=Math.min(45,maxHp(state)-state.hp),mp=Math.min(20,maxMp(state)-state.mp);state.hp+=hp;state.mp+=mp;showToast(`[ITEM USED] Minor Elixir · +${hp} HP · +${mp} MP`,'good')}item.qty--;if(item.qty<=0)state.inventory.splice(i,1);log(`[ITEM USED] ${item.name}`,'good');openPanel('inventory')}
