(()=>{
'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], SAVE_KEY='shadow-system-eternal-monarch-v1';
const pick=a=>a[Math.floor(Math.random()*a.length)], esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=null, selectedBackground='The Forgotten One';
const backgrounds={
 'The Forgotten One':{Luck:2,Perception:1},'The Exiled Hunter':{Agility:2,Strength:1},'The Unknown Awakener':{Intelligence:2,Vitality:1}
};
const baseStats=()=>({Strength:5,Agility:5,Vitality:5,Intelligence:5,Perception:5,Luck:5});
function maxHp(s=state){return 80+s.stats.Vitality*12+s.level*4}
function maxMp(s=state){return 25+s.stats.Intelligence*8+s.level*2}
function xpNeeded(level=state.level){return Math.floor(80+level*level*18)}
function save(){if(!state)return;try{localStorage.setItem(SAVE_KEY,JSON.stringify(state));$('#save-status').textContent='LOCAL SAVE SYNCED';$('#footer-message').textContent='PROGRESS SAVES AUTOMATICALLY'}catch(e){showToast('Unable to save in this browser.','warn')}}
function load(){try{const s=JSON.parse(localStorage.getItem(SAVE_KEY));if(!s||!s.name||!s.stats)return null;return s}catch{return null}}
function showToast(message,type='info'){const root=$('#toast-region');if(!root)return;const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=message;root.append(el);setTimeout(()=>el.remove(),3000)}
function log(text,type='info'){const feed=$('#event-feed');if(!feed)return;const row=document.createElement('div');row.className=`feed-event ${type}`;row.innerHTML=`<i></i><span>${esc(text)}</span>`;feed.prepend(row);while(feed.children.length>8)feed.lastChild.remove();}
function setScene(lines){$('#narrative').innerHTML=lines.map(x=>`<p>${x}</p>`).join('');}
function modal(title,message,buttons){const root=$('#modal-root');root.innerHTML=`<div class="modal-backdrop"><div class="modal-card"><span class="eyebrow">SYSTEM CONFIRMATION</span><h2>${esc(title)}</h2><p>${esc(message)}</p><div class="modal-actions">${buttons.map((b,i)=>`<button class="${i?'text-button':'primary-button'}" data-modal-action="${i}">${esc(b.label)}</button>`).join('')}</div></div></div>`;root.querySelectorAll('[data-modal-action]').forEach((b,i)=>b.onclick=()=>{root.innerHTML='';buttons[i].action()})}
function updateHud(){if(!state)return;$('#avatar-initial').textContent=state.name[0].toUpperCase();$('#hud-name').textContent=state.name;$('#hud-level').textContent=String(state.level).padStart(2,'0');$('#hud-xp').textContent=`${state.xp} / ${xpNeeded()} XP`;$('#xp-fill').style.width=`${Math.min(100,state.xp/xpNeeded()*100)}%`;$('#hud-hp').textContent=`${state.hp} / ${maxHp()}`;$('#hp-fill').style.width=`${Math.max(0,state.hp/maxHp()*100)}%`;$('#hud-mp').textContent=`MP ${state.mp} / ${maxMp()}`;$('#mp-fill').style.width=`${Math.max(0,state.mp/maxMp()*100)}%`;$('#hud-class').textContent=state.class.toUpperCase();$('#hud-background').textContent=state.background.toUpperCase();$('#hud-shadows').textContent=String(state.army.length).padStart(2,'0');$('#hud-rank').textContent=state.rank;$('#hud-currency').innerHTML=`${state.currency} <b>◈</b>`;$('#hud-location').textContent=state.location.toUpperCase();$('#day-count').textContent=`CYCLE ${String(state.day).padStart(3,'0')}`;$('#points-badge').hidden=!state.points;$('#points-badge').textContent=state.points;$('#army-badge').textContent=state.army.length;$('#guild-status').textContent=state.guild||'UNAFFILIATED';$('#world-seed').textContent=state.seed;updateQuestCard();}
function updateQuestCard(){const q=state?.quests.find(x=>x.active);$('#active-quest-card').innerHTML=q?`<strong>${esc(q.title)}</strong><p>${esc(q.description)}</p><small>${q.progress}/${q.target} · ${q.reward} ESSENCE</small>`:'<p>No active directive. Explore the frontier to find your purpose.</p>'}
function grantXp(amount){state.xp+=amount;let gained=0;while(state.xp>=xpNeeded()){state.xp-=xpNeeded();state.level++;state.points+=3;state.skillPoints++;state.hp=maxHp();state.mp=maxMp();gained++}if(gained){log(`[LEVEL UP] Level ${state.level} · +3 attribute points · +1 technique point`,'good');showToast(`[LEVEL UP] You are now level ${state.level}.`,'good')}updateHud();save()}
function createCharacter(){const name=$('#player-name').value.trim().slice(0,20)||'JOKERSKID', stats=baseStats();Object.entries(backgrounds[selectedBackground]).forEach(([k,v])=>stats[k]+=v);state={name,background:selectedBackground,class:'Awakener',level:1,xp:0,hp:100,mp:45,stats,points:0,skillPoints:1,skills:[],currency:40,rank:'E-RANK AWAKENER',army:[],inventory:[{name:'Field Ration',type:'Consumable',qty:2},{name:'Minor Elixir',type:'Consumable',qty:1}],quests:[{id:'first-gate',title:'The First Gate',description:'Enter a gate and clear a chamber.',progress:0,target:1,reward:75,kind:'room',active:true}],guild:'',relations:{},location:'The Ashen Frontier',roomType:'entrance',room:0,day:1,seed:Math.random().toString(36).slice(2,8).toUpperCase(),history:0,combat:null,pendingExtraction:null,muted:false};state.hp=maxHp();state.mp=maxMp();$('#creation-screen').hidden=true;activateGame();setScene(['The gate opens without a sound. Ash drifts across the <strong>Ashen Frontier</strong>, gathering around your boots.','Your status awakens. Beyond this threshold: a world without an ending.']);log(`[AWAKENING] ${name}, the system recognizes you.`,'good');save()}
function begin(){$('#welcome-screen').hidden=true;$('#creation-screen').hidden=false}
function activateGame(){$('#welcome-screen').hidden=true;$('#creation-screen').hidden=true;$('#game-screen').hidden=false;$('#hud').hidden=false;updateHud();openPanel('journey');if(!state.history)setScene(['A cold wind crosses the Ashen Frontier. A dormant gate shimmers at the edge of the ruins.','You are newly awakened. Choose how to begin.']);}

function actionChoices(){if(state.combat)return[{title:'Strike',detail:'Attack with your weapon.',icon:'⚔',fn:()=>combatAction('attack')},{title:'Use technique',detail:`Spend 8 MP · ${state.skills.includes('Umbral Strike')?'Umbral Strike':'focused burst'}.`,icon:'✦',fn:()=>combatAction('skill')},{title:'Guard',detail:'Reduce the next incoming hit.',icon:'⬡',fn:()=>combatAction('guard')},{title:'Retreat',detail:'Attempt to escape this encounter.',icon:'↗',fn:()=>combatAction('flee')}];
if(state.pendingExtraction)return[{title:'Arise',detail:`Attempt to bind ${state.pendingExtraction.name} (${state.pendingExtraction.chance}% chance).`,icon:'♟',fn:extractShadow},{title:'Leave the remnant',detail:'Let the shadow fade away.',icon:'⌁',fn:()=>{state.pendingExtraction=null;log('[SHADOW LOST] The remnant fades into the dark.','warn');setScene(['The shadow dissolves into a trail of violet embers.','There will be another chance.']);renderChoices();save()}}];
if(state.roomType==='entrance')return[{title:'Explore frontier',detail:'Search the outer rim for supplies, danger, or a new gate.',icon:'⌕',fn:explore},{title:'Inspect runes',detail:'Read the markings on the dormant gate.',icon:'∞',fn:inspectRunes},{title:'Enter the gate',detail:'Descend into a procedurally changing dungeon.',icon:'⇣',fn:enterDungeon},{title:'Rest',detail:'Recover some HP and MP before setting out.',icon:'✚',fn:rest}];
if(state.roomType==='cleared')return[{title:'Advance deeper',detail:'Open the next chamber of the gate.',icon:'⇣',fn:advanceRoom},{title:'Search chamber',detail:'Look for overlooked treasure.',icon:'⌕',fn:searchRoom},{title:'Return to frontier',detail:'Leave the dungeon and collect your clear reward.',icon:'↗',fn:returnFrontier},{title:'Rest',detail:'Recover some health and mana.',icon:'✚',fn:rest}];
return[{title:'Explore chamber',detail:'Press onward through the dungeon.',icon:'⌕',fn:advanceRoom},{title:'Search chamber',detail:'Search the shadows for useful items.',icon:'◇',fn:searchRoom},{title:'Retreat to gate',detail:'Abandon this run and return to the frontier.',icon:'↗',fn:returnFrontier},{title:'Use item',detail:'Open your inventory.',icon:'▤',fn:()=>openPanel('inventory')}];}
function renderChoices(){const root=$('#choices');root.innerHTML=actionChoices().map((c,i)=>`<button class="choice-button" data-choice="${i}"><span class="choice-icon">${c.icon}</span><span class="choice-copy"><strong>${esc(c.title)}</strong><small>${esc(c.detail)}</small></span><span class="choice-arrow">↗</span></button>`).join('');root.querySelectorAll('[data-choice]').forEach((b,i)=>b.onclick=()=>actionChoices()[i]?.fn());}
function openPanel(name){const journey=$('#journey-panel'),secondary=$('#secondary-panel');$$('.nav-item[data-panel]').forEach(b=>b.classList.toggle('active',b.dataset.panel===name));if(name==='journey'){journey.hidden=false;secondary.hidden=true;$('#view-title').textContent='The Ashen Frontier';$('#breadcrumb').textContent='WORLD / THE ASHEN FRONTIER';renderChoices();return}journey.hidden=true;secondary.hidden=false;$('#view-title').textContent=({character:'Character',skills:'Skill tree',inventory:'Inventory',army:'Shadow legion',quests:'Quest log',guild:'Guild',admin:'System admin'})[name]||name;$('#breadcrumb').textContent=`MONARCH INTERFACE / ${name.toUpperCase()}`;secondary.innerHTML=panelContent(name);bindPanel(name)}
function panelContent(name){if(name==='character')return `<div class="panel-card"><div class="panel-heading"><div><span class="eyebrow">AWAKENER PROFILE</span><h3>${esc(state.name)}</h3></div><span class="region-rank">LEVEL ${state.level} · ${esc(state.class.toUpperCase())}</span></div><p class="panel-description">${esc(state.background)} · ${state.points} attribute points available.</p><div class="stat-grid">${Object.entries(state.stats).map(([k,v])=>`<div class="stat-card"><span>${k.toUpperCase()}</span><strong>${v}</strong><button class="small-button" data-attribute="${k}" ${state.points?'':'disabled'}>+ Allocate</button></div>`).join('')}</div><div class="panel-card inner-card"><h4>CLASS EVOLUTION</h4><p>Reach level 10 to evolve into a Shadow Monarch and unlock class-specific bonuses.</p><button class="small-button" data-promote-class ${state.level<10?'disabled':''}>${state.class==='Awakener'?'EVOLVE CLASS':'CLASS EVOLVED'}</button></div></div>`;
if(name==='skills'){const skills=[['Umbral Strike','A focused shadow-infused attack.',1],['Monarch’s Guard','Reduce damage from the next enemy attack.',3],['Rift Step','A chance to evade the next strike.',4],['Army of One','Call your legion to deal extra damage.',6],['Domain Expansion','Overwhelm the enemy with your shadow domain.',8]];return `<div class="panel-card"><div class="panel-heading"><div><span class="eyebrow">TECHNIQUE ARCHIVE</span><h3>Skill tree</h3></div><span class="region-rank">${state.skillPoints} TECHNIQUE POINTS</span></div><p class="panel-description">Earn one technique point each time you level up.</p><div class="list-stack">${skills.map(([n,d,c])=>`<div class="list-card"><div><strong>${esc(n)}</strong><p>${esc(d)}</p><small>COST ${c} · ${state.skills.includes(n)?'UNLOCKED':state.skillPoints>=c?'AVAILABLE':'LOCKED'}</small></div><button class="small-button" data-skill="${esc(n)}" ${state.skills.includes(n)||state.skillPoints<c?'disabled':''}>${state.skills.includes(n)?'LEARNED':`UNLOCK · ${c}`}</button></div>`).join('')}</div></div>`}
if(name==='inventory')return `<div class="panel-card"><div class="panel-heading"><div><span class="eyebrow">CARRIED ITEMS</span><h3>Inventory</h3></div><span class="region-rank">${state.inventory.reduce((n,x)=>n+x.qty,0)} ITEMS</span></div>${state.inventory.length?`<div class="list-stack">${state.inventory.map((x,i)=>`<div class="list-card"><div><strong>${esc(x.name)} <span class="item-qty">×${x.qty}</span></strong><p>${x.type==='Consumable'?'A single-use restorative supply.':'A useful item.'}</p><small>${esc(x.type.toUpperCase())}</small></div><button class="small-button" data-use-item="${i}" ${x.type!=='Consumable'?'disabled':''}>USE</button></div>`).join('')}</div>`:'<p class="empty-state">Your pack is empty. Search the frontier and dungeon chambers for supplies.</p>'}</div>`;
if(name==='army')return `<div class="panel-card"><div class="panel-heading"><div><span class="eyebrow">SHADOW EXTRACTION</span><h3>Your legion</h3></div><span class="region-rank">${state.army.length} BOUND</span></div><p class="panel-description">Defeat elite and boss enemies, then type ARISE to attempt to bind their shadow.</p><div class="panel-actions"><button id="army-scout" class="small-button">SCOUT FRONTIER</button><button id="army-drill" class="small-button" ${state.army.length?'':'disabled'}>DRILL · ${15+state.level*2} ESSENCE</button></div>${state.army.length?`<div class="list-stack">${state.army.map((x,i)=>`<div class="list-card"><div><strong>${esc(x.name)}</strong><p>Level ${x.level} · Loyalty ${x.loyalty}%</p><small>${esc(x.rank.toUpperCase())}</small></div><button class="small-button" data-promote="${i}" ${x.rank==='General'?'disabled':''}>PROMOTE · ${30+state.level*4}</button></div>`).join('')}</div>`:'<p class="empty-state">No shadows bound. The worthy wait beyond the next gate.</p>'}</div>`;

if(name==='quests')return `<div class="panel-card"><div class="panel-heading"><div><span class="eyebrow">DIRECTIVES</span><h3>Quest log</h3></div><span class="region-rank">${state.quests.filter(x=>x.active).length} ACTIVE</span></div><div class="list-stack">${state.quests.map(q=>`<div class="list-card"><div><strong>${esc(q.title)}</strong><p>${esc(q.description)}</p><small>${q.active?`${q.progress}/${q.target} · ${q.reward} ESSENCE`:'COMPLETE'}</small></div><span class="quest-progress">${q.active?'IN PROGRESS':'✓'}</span></div>`).join('')}</div></div>`;
if(name==='guild')return `<div class="panel-card"><div class="panel-heading"><div><span class="eyebrow">HUNTER ASSOCIATION</span><h3>${state.guild?esc(state.guild):'Choose an oath'}</h3></div><span class="region-rank">${state.guild?'MEMBER':'UNAFFILIATED'}</span></div><p class="panel-description">Guild membership provides contracts and a place in the hunter community.</p>${state.guild?`<button id="guild-contract" class="small-button">ACCEPT GATE SURVEY CONTRACT</button>`:`<div class="list-stack">${['Hunters Guild','Night Watch','Free Awakeners'].map(g=>`<div class="list-card"><div><strong>${g}</strong><p>${g==='Hunters Guild'?'Pragmatic professionals with a strict ranking system.':g==='Night Watch'?'Guardians who protect settlements from the dark.':'Independent hunters who value freedom.'}</p></div><button class="small-button" data-join-guild="${g}">JOIN</button></div>`).join('')}</div>`}</div>`;
if(name==='admin')return `<div class="panel-card"><div class="panel-heading"><div><span class="eyebrow">LOCAL SANDBOX</span><h3>System admin</h3></div><span class="region-rank">DEVELOPMENT</span></div><p class="panel-description">Testing controls affect this browser's save. They are not a server-side admin system.</p><div class="list-stack">${[['xp','Grant 500 XP'],['currency','Grant 500 essence'],['heal','Restore HP and MP'],['level','Grant five levels'],['shadow','Summon test shadow']].map(([a,b])=>`<div class="list-card"><strong>${b}</strong><button class="small-button" data-admin="${a}">EXECUTE</button></div>`).join('')}</div><button id="delete-save" class="danger-button">RESET LOCAL SAVE</button></div>`;
return '<div class="panel-card"><p class="empty-state">Panel unavailable.</p></div>'}
function bindPanel(){ $$('[data-attribute]').forEach(b=>b.onclick=()=>{const key=b.dataset.attribute;if(!state.points)return;state.stats[key]++;state.points--;if(key==='Vitality')state.hp+=12;if(key==='Intelligence')state.mp+=8;log(`[ATTRIBUTE INCREASED] ${key} is now ${state.stats[key]}.`,'good');openPanel('character');updateHud();save()});$$('[data-skill]').forEach(b=>b.onclick=()=>{const skill=b.dataset.skill,need=skill==='Umbral Strike'?1:skill==='Monarch’s Guard'?3:skill==='Rift Step'?4:skill==='Army of One'?6:8;if(state.skills.includes(skill)||state.skillPoints<need)return;state.skills.push(skill);state.skillPoints-=need;log(`[TECHNIQUE UNLOCKED] ${skill}.`,'good');showToast(`[TECHNIQUE UNLOCKED] ${skill}`,'good');openPanel('skills');save()});$$('[data-use-item]').forEach(b=>b.onclick=()=>useItem(Number(b.dataset.useItem)));$$('[data-promote]').forEach(b=>b.onclick=()=>promote(Number(b.dataset.promote)));$$('[data-join-guild]').forEach(b=>b.onclick=()=>joinGuild(b.dataset.joinGuild));$$('[data-admin]').forEach(b=>b.onclick=()=>adminAction(b.dataset.admin));const scout=$('#army-scout');if(scout)scout.onclick=()=>{openPanel('journey');scoutArmy()};const drill=$('#army-drill');if(drill)drill.onclick=()=>{const cost=15+state.level*2;if(!state.army.length)return;if(state.currency<cost){showToast(`Need ${cost} essence to drill.`,'warn');return}state.currency-=cost;state.army.forEach(x=>x.loyalty=Math.min(100,x.loyalty+4));grantXp(10);log(`[LEGION DRILL] Loyalty increased · −${cost} essence`,'good');openPanel('army');save()};const contract=$('#guild-contract');if(contract)contract.onclick=guildContract;const evolve=$('[data-promote-class]');if(evolve)evolve.onclick=()=>{if(state.level<10||state.class!=='Awakener')return;state.class='Shadow Monarch';state.rank='S-RANK AWAKENER';state.stats.Strength+=3;state.stats.Vitality+=3;log('[CLASS EVOLUTION] You have become the Shadow Monarch.','good');showToast('[CLASS EVOLUTION] Shadow Monarch','good');openPanel('character');updateHud();save()};$('#delete-save')?.addEventListener('click',()=>modal('RESET LOCAL SAVE?','This permanently erases your current character and all progress from this browser.',[{label:'RESET SAVE',action:()=>{localStorage.removeItem(SAVE_KEY);location.reload()}},{label:'CANCEL',action:()=>{}}]));}
function useItem(i){const item=state.inventory[i];if(!item||item.type!=='Consumable')return;const hp=Math.min(item.name==='Field Ration'?35:45,maxHp()-state.hp),mp=item.name==='Field Ration'?0:Math.min(20,maxMp()-state.mp);if(!hp&&!mp){showToast('Your HP and MP are already full.','warn');return}state.hp+=hp;state.mp+=mp;item.qty--;if(item.qty<=0)state.inventory.splice(i,1);log(`[ITEM USED] ${item.name} · +${hp} HP · +${mp} MP`,'good');openPanel('inventory');updateHud();save()}
function promote(i){const sh=state.army[i];if(!sh||sh.rank==='General')return;const cost=30+state.level*4;if(state.currency<cost){showToast(`Need ${cost} essence to promote.`,'warn');return}state.currency-=cost;sh.rank=sh.rank==='Elite'?'Knight':'General';sh.loyalty=100;log(`[SHADOW PROMOTION] ${sh.name} is now ${sh.rank}.`,'good');showToast(`[SHADOW PROMOTION] ${sh.name} → ${sh.rank}`,'good');openPanel('army');updateHud();save()}
function joinGuild(name){if(state.guild)return;state.guild=name;state.relations[name]=5;log(`[GUILD JOINED] ${name} has accepted your oath.`,'good');showToast(`[GUILD JOINED] ${name}`,'good');openPanel('guild');updateHud();save()}
function guildContract(){if(!state.guild)return;const q={id:`guild-${Date.now()}`,title:'Guild Contract: Gate Survey',description:'Complete the next gate chamber and report what you find.',progress:0,target:1,reward:90+state.level*8,kind:'room',active:true};state.quests.push(q);log(`[GUILD CONTRACT] ${q.title} · reward ${q.reward} essence`,'good');showToast('[GUILD CONTRACT] New directive added.','good');openPanel('quests');save()}
function adminAction(action){if(action==='xp')grantXp(500);if(action==='currency')state.currency+=500;if(action==='heal'){state.hp=maxHp();state.mp=maxMp()}if(action==='level')grantXp(xpNeeded()*5);if(action==='shadow')state.army.push({name:`Bound Sentinel ${state.army.length+1}`,rank:'Elite',level:state.level,loyalty:100});log(`[ADMIN] ${action} applied.`,'good');showToast('[SYSTEM ADMIN] Local sandbox updated.','good');openPanel('admin');updateHud();save()}

function newEnemy(boss=false,elite=false){const names=boss?['Gate Warden','Ashen Tyrant','Hollow Monarch']:elite?['Rift Stalker','Grave Knight','Dread Hound']:['Ash Wisp','Feral Shade','Ruin Crawler','Hollowed Hunter'];const scale=1+state.level*.12+state.room*.08;return{name:pick(names),boss,elite,hp:Math.floor((boss?95:elite?65:35)*scale),maxHp:Math.floor((boss?95:elite?65:35)*scale),attack:Math.floor((boss?17:elite?12:8)*scale)}}
function explore(){if(state.combat)return;state.day++;state.history++;const roll=Math.random();if(roll<.43){state.currency+=8+state.level*2;state.inventory.push({name:'Field Ration',type:'Consumable',qty:1});setScene(['You follow a trail of broken stones beneath the ash. A hunter’s pack lies beside a collapsed arch.','You recover a field ration and a small cache of essence.']);log('[FRONTIER] Supplies recovered.','good')}else if(roll<.78){const elite=Math.random()<.14;startCombat(newEnemy(false,elite),'field');setScene([`The ash parts. A <strong>${state.combat.enemy.name}</strong> blocks your way.`,`It turns toward you. There is no time to retreat unnoticed.`]);log(`[ENCOUNTER] ${state.combat.enemy.name} emerged from the ash.`,'warn')}else{setScene(['A dormant gate flickers to life among the ruins. Its inner surface ripples like dark water.','A fresh dungeon awaits. The gate will remain open until you choose to enter.']);state.roomType='entrance'}grantXp(5+state.level);updateHud();renderChoices();save()}
function inspectRunes(){state.history++;const lines=['The runes shift into a language you almost remember.','The gate is unstable, but its heart beats in time with your own.','A warning: “The deeper the shadow, the more it remembers.”'];setScene([pick(lines),'The markings suggest the gate is open. Enter when ready.']);state.mp=Math.min(maxMp(),state.mp+3);renderChoices();save()}
function enterDungeon(){state.room=1;state.roomType='combat';state.location='The Umbral Gate';state.day++;const boss=Math.random()<.12;startCombat(newEnemy(boss,!boss&&Math.random()<.2),'dungeon');setScene([`You cross the threshold into <strong>Chamber ${state.room}</strong>. The gate seals behind you.`,`A ${state.combat.enemy.name} descends from the dark.`]);log('[GATE ENTERED] Dungeon instance generated.','info');updateHud();renderChoices();save()}
function advanceRoom(){state.room++;state.roomType='combat';state.day++;const boss=state.room%5===0||Math.random()<.1;startCombat(newEnemy(boss,!boss&&Math.random()<.23),'dungeon');setScene([`The passage folds open into <strong>Chamber ${state.room}</strong>.`,`${state.combat.enemy.boss?'A gate boss':'A hostile shadow'} blocks your path: ${state.combat.enemy.name}.`]);log(`[DUNGEON] Chamber ${state.room} · ${state.combat.enemy.name}`,'warn');renderChoices();save()}
function startCombat(enemy,origin){state.combat={enemy,origin,guard:false};renderChoices()}
function combatAction(action){const c=state.combat;if(!c)return;const enemy=c.enemy;let damage=0;if(action==='flee'){if(c.origin==='field'||Math.random()<.45){state.combat=null;state.roomType=c.origin==='dungeon'?'cleared':'entrance';setScene(['You find a moment to withdraw. The dark closes behind you.','You return to a safer distance.']);log('[RETREAT] You escaped the encounter.','warn')}else{showToast('The enemy blocks your escape!','warn')}}else if(action==='guard'){c.guard=true;setScene([`You settle into a guarded stance as ${esc(enemy.name)} circles.`,`The next incoming attack will be reduced.`])}else{if(action==='skill'){if(state.mp<8){showToast('Not enough MP for a technique.','warn');damage=Math.max(2,state.stats.Strength+Math.floor(Math.random()*6))}else{state.mp-=8;damage=state.stats.Intelligence+state.stats.Strength+Math.floor(Math.random()*12)+(state.skills.includes('Umbral Strike')?12:0);if(state.skills.includes('Army of One')&&state.army.length)damage+=state.army.length*7;if(state.skills.includes('Domain Expansion'))damage+=14}}else damage=state.stats.Strength+Math.floor(Math.random()*9)+3;enemy.hp-=damage;setScene([`You ${action==='skill'?'unleash a technique':'strike'} for <strong>${damage} damage</strong>.`,`<strong>${esc(enemy.name)}</strong> · ${Math.max(0,enemy.hp)} / ${enemy.maxHp} HP`]);if(enemy.hp<=0){winCombat();return}}
const incoming=Math.max(1,enemy.attack+Math.floor(Math.random()*6)-Math.floor(state.stats.Agility/4));const hit=c.guard?Math.ceil(incoming*.35):incoming;state.hp=Math.max(0,state.hp-hit);c.guard=false;if(state.hp<=0){state.hp=Math.ceil(maxHp()*.35);state.mp=Math.ceil(maxMp()*.35);state.combat=null;state.roomType='entrance';state.location='The Ashen Frontier';state.currency=Math.max(0,state.currency-10);setScene(['Darkness folds around you. The gate ejects you before the final blow.','You awaken at the frontier, weakened, but alive. A small essence fee was lost.']);log('[DEFEAT] The gate returned you to the frontier.','warn')}else setScene([`You take <strong>${hit} damage</strong>. ${c.guard?'Your guard absorbed part of the blow.':''}`,`<strong>${esc(enemy.name)}</strong> · ${enemy.hp} / ${enemy.maxHp} HP · Your HP ${state.hp}/${maxHp()}`]);updateHud();renderChoices();save()}
function winCombat(){const c=state.combat,e=c.enemy;state.combat=null;state.currency+=e.boss?55+state.level*5:e.elite?26+state.level*3:12+state.level*2;grantXp(e.boss?70+state.level*12:e.elite?40+state.level*7:20+state.level*4);if(Math.random()<.2)state.inventory.push({name:'Minor Elixir',type:'Consumable',qty:1});if(e.elite||e.boss)state.pendingExtraction={name:e.name,chance:e.boss?85:65};if(c.origin==='dungeon'){state.roomType='cleared';state.quests.forEach(q=>{if(q.active&&q.kind==='room'){q.progress++;if(q.progress>=q.target){q.active=false;state.currency+=q.reward;log(`[QUEST COMPLETE] ${q.title} · +${q.reward} essence`,'good')}}})}else state.roomType='entrance';setScene([`<strong>${esc(e.name)}</strong> is defeated. Essence gathers around you.`,`You earned XP and essence.${state.pendingExtraction?` The shadow remains. Type <strong>ARISE</strong> to attempt extraction.`:''}`]);log(`[VICTORY] ${e.name} defeated.`,'good');updateHud();renderChoices();save()}
function extractShadow(){const p=state.pendingExtraction;if(!p){showToast('No shadow is ready to bind. Defeat an elite or boss first.','warn');return}if(Math.random()*100<=p.chance){state.army.push({name:p.name,rank:'Elite',level:state.level,loyalty:75});log(`[SHADOW BOUND] ${p.name} joins your legion.`,'good');showToast(`[SHADOW BOUND] ${p.name}`,'good');state.pendingExtraction=null;setScene([`The shadow rises. <strong>${esc(p.name)}</strong> kneels and joins your legion.`,`Your army now contains ${state.army.length} bound shadow${state.army.length===1?'':'s'}.`])}else{p.chance=Math.max(15,p.chance-25);log('[SHADOW EXTRACTION] The binding failed. The remnant weakens.','warn');showToast('[SHADOW EXTRACTION] Binding failed.','warn');if(p.chance<=15)state.pendingExtraction=null;setScene(['The shadow resists your command and tears free.','The remnant is weaker now, but you may still attempt to bind it.'])}updateHud();renderChoices();save()}

function searchRoom(){if(state.roomType==='combat'||state.combat){showToast('Defeat the chamber guardian before searching.','warn');return}if(Math.random()<.58){const amount=12+state.level*3;state.currency+=amount;const item=pick(['Field Ration','Minor Elixir']);state.inventory.push({name:item,type:'Consumable',qty:1});setScene([`Behind a cracked pillar, you find <strong>${amount} essence</strong> and a ${item}.`,'The chamber has nothing else to offer.']);log(`[DUNGEON LOOT] +${amount} essence · ${item}`,'good')}else{setScene(['Your search turns up only ash, old bones, and a faint trail of violet dust.','You hear movement deeper in the gate.']);if(state.roomType==='cleared')state.roomType='combat'}renderChoices();updateHud();save()}
function returnFrontier(){if(state.combat){showToast('You must retreat from combat first.','warn');return}state.roomType='entrance';state.location='The Ashen Frontier';state.room=0;state.currency+=15+state.level*2;setScene(['You pass back through the gate. Its surface seals with a soft shiver.','A small clear bonus is credited to your account. The frontier awaits.']);log('[GATE CLEARED] Returned to the Ashen Frontier.','good');updateHud();renderChoices();save()}
function rest(){const hp=Math.min(35+state.level*3,maxHp()-state.hp),mp=Math.min(20+state.level,maxMp()-state.mp);if(!hp&&!mp){showToast('You are already fully restored.','info');return}state.hp+=hp;state.mp+=mp;state.day++;setScene([`You take shelter and recover <strong>${hp} HP</strong> and <strong>${mp} MP</strong>.`,'The ash settles. Your journey continues.']);log(`[REST] +${hp} HP · +${mp} MP`,'good');updateHud();renderChoices();save()}
function scoutArmy(){if(!state.army.length){showToast('Your legion is empty. Bind a shadow after defeating an elite or boss.','warn');return}if(Math.random()<.55){state.currency+=14+state.level*2;grantXp(8);setScene(['Your scouts return with a small cache of essence.','The legion reports no immediate threat.'])}else{startCombat(newEnemy(false,false),'field');setScene([`Your shadows return with a hostile presence on their trail: <strong>${state.combat.enemy.name}</strong>.`])}renderChoices();updateHud();save()}
function submitCustom(text){const raw=text.trim();if(!raw)return;$('#custom-action-input').value='';if(/^arise\b/i.test(raw)){extractShadow();return}if(/\bhelp\b/i.test(raw)){showToast('Try: explore, inspect runes, enter the gate, search, rest, or ARISE after an elite/boss victory.');return}if(/inventory|bag|items|pack/i.test(raw)){openPanel('inventory');return}if(/status|stats|character|level/i.test(raw)){openPanel('character');return}if(/army|shadow|legion/i.test(raw)&&!state.combat){openPanel('army');return}if(/quest|directive/i.test(raw)&&!state.combat){openPanel('quests');return}if(state.combat){const low=raw.toLowerCase();combatAction(/guard|defend|block/i.test(low)?'guard':/skill|magic|spell|shadow/i.test(low)?'skill':/run|flee|escape|retreat/i.test(low)?'flee':'attack');return}if(/rest|heal|recover/i.test(raw)){rest();return}if(/scout/i.test(raw)){state.army.length?scoutArmy():explore();return}if(/rune|inspect|read/i.test(raw)&&state.roomType==='entrance'){inspectRunes();return}if(/enter|dungeon|gate|descend/i.test(raw)){state.roomType==='entrance'||state.roomType==='cleared'?enterDungeon():advanceRoom();return}if(/search|loot|look|investigate/i.test(raw)){searchRoom();return}if(/leave|return|exit/i.test(raw)&&state.roomType!=='entrance'){returnFrontier();return}if(state.pendingExtraction){showToast('A shadow extraction is ready. Type ARISE to attempt the binding.','warn');return}const xp=6+state.level*2;grantXp(xp);state.history++;if(Math.random()<.2){startCombat(newEnemy(false,false),'field');setScene([`You attempt: “${esc(raw)}.” The frontier answers with a sudden interruption.`,`A hostile presence takes shape ahead.`]);log('[CUSTOM ACTION] The frontier responded with an encounter.','warn')}else{setScene([`You attempt: “${esc(raw)}.” ${pick(['The world tilts around your intent. A thin violet seam appears, then seals itself behind you.','For a heartbeat, every shadow nearby turns in your direction. Somewhere beyond the gate, something answers.','Your action leaves a mark in the ash. The system records it as a new possibility.','The gate hums in recognition. The path ahead shifts.'])}`,`<strong class="system-note">[ACTION RECORDED] +${xp} XP · The world remembers what you try.</strong>`]);log(`[CUSTOM ACTION] ${raw.slice(0,55)} · +${xp} XP`,'info')}renderChoices();save()}
$('#begin-button').addEventListener('click',begin);$('#continue-button').addEventListener('click',()=>{state=load();if(!state){showToast('No valid local save was found.','warn');return}activateGame();log('[SAVE RESTORED] Your journey resumes.','good')});$('#back-welcome').addEventListener('click',()=>{$('#creation-screen').hidden=true;$('#welcome-screen').hidden=false});$$('.background-card').forEach(b=>b.addEventListener('click',()=>{selectedBackground=b.dataset.background;$$('.background-card').forEach(x=>x.classList.toggle('selected',x===b))}));$('#create-character').addEventListener('click',createCharacter);$('#custom-action-form').addEventListener('submit',e=>{e.preventDefault();submitCustom($('#custom-action-input').value)});$$('.nav-item[data-panel]').forEach(b=>b.addEventListener('click',()=>openPanel(b.dataset.panel)));$$('[data-open-panel]').forEach(b=>b.addEventListener('click',()=>openPanel(b.dataset.openPanel)));$('#save-button').addEventListener('click',()=>{save();showToast('[SYSTEM] Local save confirmed.','good')});$('#exit-button').addEventListener('click',()=>modal('RETURN TO TITLE?','Your progress is automatically saved. You can continue your run whenever you return.',[{label:'RETURN TO TITLE',action:()=>{save();$('#game-screen').hidden=true;$('#hud').hidden=true;$('#welcome-screen').hidden=false;$('#continue-button').hidden=false}},{label:'STAY HERE',action:()=>{}}]));$('#sound-toggle').addEventListener('click',()=>{if(!state){showToast('Sound effects are not enabled in this build.');return}state.muted=!state.muted;$('#sound-toggle').textContent=state.muted?'♫̸':'♫';showToast(state.muted?'Sound effects muted.':'Sound effects enabled.')});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#modal-root').innerHTML)$('#modal-root').innerHTML='';if(!state||$('#game-screen').hidden||e.target.matches('input,textarea'))return;if(/^[1-4]$/.test(e.key)){actionChoices()[Number(e.key)-1]?.fn()}if(e.key.toLowerCase()==='i')openPanel('inventory');if(e.key.toLowerCase()==='c')openPanel('character')});
state=load();if(state){$('#continue-button').hidden=false;$('#begin-button').textContent='NEW AWAKENING'}else $('#continue-button').hidden=true;
})();

