(()=>{
'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const SAVE_KEY='shadow-system-eternal-monarch-v1';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pick=a=>a[Math.floor(Math.random()*a.length)];
let state=null, selectedBackground='The Forgotten One';
const backgrounds={
 'The Forgotten One':{Luck:2,Perception:1},
 'The Exiled Hunter':{Agility:2,Strength:1},
 'The Unknown Awakener':{Intelligence:2,Vitality:1}
};
const baseStats=()=>({Strength:5,Agility:5,Vitality:5,Intelligence:5,Perception:5,Luck:5});
function maxHp(){return 80+state.stats.Vitality*12+state.level*4}
function maxMp(){return 25+state.stats.Intelligence*8+state.level*2}
function xpNeeded(){return Math.floor(80+state.level*state.level*18)}
function save(){if(!state)return;try{localStorage.setItem(SAVE_KEY,JSON.stringify(state));$('#save-status').textContent='LOCAL SAVE SYNCED';$('#footer-message').textContent='PROGRESS SAVES AUTOMATICALLY'}catch{showToast('Unable to save in this browser.','warn')}}
function load(){try{const s=JSON.parse(localStorage.getItem(SAVE_KEY));return s&&s.name&&s.stats?s:null}catch{return null}}
function showToast(message,type='info'){const root=$('#toast-region');const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=message;root.append(el);setTimeout(()=>el.remove(),3000)}
function log(text,type='info'){const feed=$('#event-feed'),row=document.createElement('div');row.className=`feed-event ${type}`;row.innerHTML=`<i></i><span>${esc(text)}</span>`;feed.prepend(row);while(feed.children.length>8)feed.lastChild.remove()}
function setScene(lines){$('#narrative').innerHTML=lines.map(x=>`<p>${x}</p>`).join('');$('#scene-location').textContent=state.location.toUpperCase();$('#scene-time').textContent=`CYCLE ${String(state.day).padStart(3,'0')}`;$('#scene-tag').textContent=`FIELD REPORT · ${String(state.history+1).padStart(3,'0')}`}
function modal(title,message,buttons){const root=$('#modal-root');root.innerHTML=`<div class="modal-backdrop"><div class="modal-card"><span class="eyebrow">SYSTEM CONFIRMATION</span><h2>${esc(title)}</h2><p>${esc(message)}</p><div class="modal-actions">${buttons.map((b,i)=>`<button class="${i?'text-button':'primary-button'}" data-modal-action="${i}">${esc(b.label)}</button>`).join('')}</div></div></div>`;root.querySelectorAll('[data-modal-action]').forEach((b,i)=>b.onclick=()=>{root.innerHTML='';buttons[i].action()})}
function updateQuestCard(){const q=state.quests.find(x=>x.active);$('#active-quest-card').innerHTML=q?`<strong>${esc(q.title)}</strong><p>${esc(q.description)}</p><small>${q.progress}/${q.target} · ${q.reward} ESSENCE</small>`:'<p>No active directive. Explore the frontier to find your purpose.</p>'}
function updateHud(){if(!state)return;$('#avatar-initial').textContent=state.name[0].toUpperCase();$('#hud-name').textContent=state.name;$('#hud-level').textContent=String(state.level).padStart(2,'0');$('#hud-xp').textContent=`${state.xp} / ${xpNeeded()} XP`;
$('#xp-fill').style.width=`${Math.min(100,state.xp/xpNeeded()*100)}%`;$('#hud-hp').textContent=`${state.hp} / ${maxHp()}`;$('#hp-fill').style.width=`${Math.max(0,state.hp/maxHp()*100)}%`;$('#hud-mp').textContent=`MP ${state.mp} / ${maxMp()}`;$('#mp-fill').style.width=`${Math.max(0,state.mp/maxMp()*100)}%`;
$('#hud-class').textContent=state.class.toUpperCase();$('#hud-background').textContent=state.background.toUpperCase();$('#hud-shadows').textContent=String(state.army.length).padStart(2,'0');$('#hud-rank').textContent=state.rank;$('#hud-currency').innerHTML=`${state.currency} <b>◈</b>`;$('#hud-location').textContent=state.location.toUpperCase();$('#day-count').textContent=`CYCLE ${String(state.day).padStart(3,'0')}`;$('#points-badge').hidden=!state.points;$('#points-badge').textContent=state.points;$('#army-badge').textContent=state.army.length;$('#guild-status').textContent=state.guild||'UNAFFILIATED';$('#region-rank').textContent=state.roomType==='entrance'?'F-RANK REGION':`GATE · CHAMBER ${state.room}`;$('#world-seed').textContent=state.seed;updateQuestCard()}
function grantXp(amount){state.xp+=amount;let gained=0;while(state.xp>=xpNeeded()){state.xp-=xpNeeded();state.level++;state.points+=3;state.skillPoints++;state.hp=maxHp();state.mp=maxMp();gained++}if(gained){log(`[LEVEL UP] Level ${state.level} · +3 attribute points · +1 technique point`,'good');showToast(`[LEVEL UP] You are now level ${state.level}.`,'good')}updateHud();save()}
function createCharacter(){const name=$('#player-name').value.trim().slice(0,20)||'JOKERSKID',stats=baseStats();Object.entries(backgrounds[selectedBackground]).forEach(([k,v])=>stats[k]+=v);state={name,background:selectedBackground,class:'Awakener',level:1,xp:0,hp:100,mp:45,stats,points:0,skillPoints:1,skills:[],currency:40,rank:'E-RANK AWAKENER',army:[],inventory:[{name:'Field Ration',type:'Consumable',qty:2},{name:'Minor Elixir',type:'Consumable',qty:1}],quests:[{id:'first-gate',title:'The First Gate',description:'Enter a gate and clear a chamber.',progress:0,target:1,reward:75,kind:'room',active:true}],guild:'',relations:{},location:'The Ashen Frontier',roomType:'entrance',room:0,day:1,seed:Math.random().toString(36).slice(2,8).toUpperCase(),history:0,combat:null,pendingExtraction:null,muted:false};state.hp=maxHp();state.mp=maxMp();$('#creation-screen').hidden=true;activateGame();setScene(['The gate opens without a sound. Ash drifts across the <strong>Ashen Frontier</strong>, gathering around your boots.','Your status awakens. Beyond this threshold: a world without an ending.']);log(`[AWAKENING] ${name}, the system recognizes you.`,'good');save()}
function begin(){$('#welcome-screen').hidden=true;$('#creation-screen').hidden=false}
function activateGame(){$('#welcome-screen').hidden=true;$('#creation-screen').hidden=true;$('#game-screen').hidden=false;$('#hud').hidden=false;updateHud();openPanel('journey');if(!state.history)setScene(['A cold wind crosses the Ashen Frontier. A dormant gate shimmers at the edge of the ruins.','You are newly awakened. Choose how to begin.'])}

