function activateGame(){$('#welcome-screen').hidden=true;$('#creation-screen').hidden=true;$('#game-screen').hidden=false;$('#hud').hidden=false;updateHud();openPanel('journey');if(!state.history)setScene(['A cold wind crosses the Ashen Frontier. A dormant gate shimmers at the edge of the ruins.','You are newly awakened. Choose how to begin.'])}
function actionChoices(){if(state.combat)return[{title:'Strike',detail:'Attack with your weapon.',icon:'⚔',fn:()=>combatAction('attack')},{title:'Use technique',detail:'Spend 8 MP · focused shadow burst.',icon:'✦',fn:()=>combatAction('skill')},{title:'Guard',detail:'Reduce the next incoming hit.',icon:'⬡',fn:()=>combatAction('guard')},{title:'Retreat',detail:'Attempt to escape this encounter.',icon:'↗',fn:()=>combatAction('flee')}];if(state.pendingExtraction)return[{title:'Arise',detail:`Bind ${state.pendingExtraction.name} (${state.pendingExtraction.chance}% chance).`,icon:'♟',fn:extractShadow},{title:'Leave remnant',detail:'Let the shadow fade away.',icon:'⌁',fn:()=>{state.pendingExtraction=null;setScene(['The shadow dissolves into violet embers.','There will be another chance.']);renderChoices();save()}}];if(state.roomType==='entrance')return[{title:'Explore frontier',detail:'Search for supplies, danger, or a new gate.',icon:'⌕',fn:explore},{title:'Inspect runes',detail:'Read the markings on the dormant gate.',icon:'∞',fn:inspectRunes},{title:'Enter the gate',detail:'Descend into a procedurally changing dungeon.',icon:'⇣',fn:enterDungeon},{title:'Rest',detail:'Recover HP and MP before setting out.',icon:'✚',fn:rest}];if(state.roomType==='cleared')return[{title:'Advance deeper',detail:'Open the next chamber of the gate.',icon:'⇣',fn:advanceRoom},{title:'Search chamber',detail:'Look for overlooked treasure.',icon:'⌕',fn:searchRoom},{title:'Return to frontier',detail:'Leave the dungeon and collect a clear reward.',icon:'↗',fn:returnFrontier},{title:'Rest',detail:'Recover health and mana.',icon:'✚',fn:rest}];return[{title:'Explore chamber',detail:'Press onward through the dungeon.',icon:'⌕',fn:advanceRoom},{title:'Search chamber',detail:'Search the shadows for useful items.',icon:'◇',fn:searchRoom},{title:'Retreat to gate',detail:'Abandon this run and return to the frontier.',icon:'↗',fn:returnFrontier},{title:'Use item',detail:'Open your inventory.',icon:'▤',fn:()=>openPanel('inventory')}]}
function renderChoices(){const root=$('#choices');root.innerHTML=actionChoices().map((c,i)=>`<button class="choice-button" data-choice="${i}"><span class="choice-icon">${c.icon}</span><span class="choice-copy"><strong>${esc(c.title)}</strong><small>${esc(c.detail)}</small></span><span class="choice-arrow">↗</span></button>`).join('');root.querySelectorAll('[data-choice]').forEach((b,i)=>b.onclick=()=>actionChoices()[i]?.fn())}
function openPanel(name){const journey=$('#journey-panel'),secondary=$('#secondary-panel');$$('.nav-item[data-panel]').forEach(b=>b.classList.toggle('active',b.dataset.panel===name));if(name==='journey'){journey.hidden=false;secondary.hidden=true;$('#view-title').textContent='The Ashen Frontier';$('#breadcrumb').textContent='WORLD / THE ASHEN FRONTIER';renderChoices();return}journey.hidden=true;secondary.hidden=false;$('#view-title').textContent=({character:'Character',skills:'Skill tree',inventory:'Inventory',army:'Shadow legion',quests:'Quest log',guild:'Guild',admin:'System admin'})[name]||name;$('#breadcrumb').textContent=`MONARCH INTERFACE / ${name.toUpperCase()}`;secondary.innerHTML=panelContent(name);bindPanel()}
function panelContent(name){if(name==='character')return `<div class="panel-card"><div class="panel-heading"><div><span class="eyebrow">AWAKENER PROFILE</span><h3>${esc(state.name)}</h3></div><span class="region-rank">LEVEL ${state.level} · ${esc(state.class.toUpperCase())}</span></div><p class="panel-description">${esc(state.background)} · ${state.points} attribute points available.</p><div class="stat-grid">${Object.entries(state.stats).map(([k,v])=>`<div class="stat-card"><span>${k.toUpperCase()}</span><strong>${v}</strong><button class="small-button" data-attribute="${k}" ${state.points?'':'disabled'}>+ Allocate</button></div>`).join('')}</div><div class="panel-card inner-card"><h4>CLASS EVOLUTION</h4><p>Reach level 10 to evolve into a Shadow Monarch and unlock class-specific bonuses.</p><button class="small-button" data-promote-class ${state.level<10||state.class!=='Awakener'?'disabled':''}>${state.class==='Awakener'?'EVOLVE CLASS':'CLASS EVOLVED'}</button></div></div>`;
if(name==='skills'){const skills=[['Umbral Strike','A focused shadow-infused attack.',1],['Monarch’s Guard','Reduce damage from the next enemy attack.',3],['Rift Step','A chance to evade the next strike.',4],['Army of One','Call your legion to deal extra damage.',6],['Domain Expansion','Overwhelm the enemy with your shadow domain.',8]];return `<div class="panel-card"><div class="panel-heading"><div><span class="eyebrow">TECHNIQUE ARCHIVE</span><h3>Skill tree</h3></div><span class="region-rank">${state.skillPoints} TECHNIQUE POINTS</span></div><p class="panel-description">Earn one technique point each time you level up.</p><div class="list-stack">${skills.map(([n,d,c])=>`<div class="list-card"><div><strong>${esc(n)}</strong><p>${esc(d)}</p><small>COST ${c} · ${state.skills.includes(n)?'UNLOCKED':state.skillPoints>=c?'AVAILABLE':'LOCKED'}</small></div><button class="small-button" data-skill="${esc(n)}" ${state.skills.includes(n)||state.skillPoints<c?'disabled':''}>${state.skills.includes(n)?'LEARNED':`UNLOCK · ${c}`}</button></div>`).join('')}</div></div>`}
if(name==='inventory')return `<div class="panel-card"><div class="panel-heading"><div><span class="eyebrow">CARRIED ITEMS</span><h3>Inventory</h3></div><span class="region-rank">${state.inventory.reduce((n,x)=>n+x.qty,0)} ITEMS</span></div>${state.inventory.length?`<div class="list-stack">${state.inventory.map((x,i)=>`<div class="list-card"><div><strong>${esc(x.name)} <span class="item-qty">×${x.qty}</span></strong><p>${x.type==='Consumable'?'A single-use restorative supply.':'A useful item.'}</p><small>${esc(x.type.toUpperCase())}</small></div><button class="small-button" data-use-item="${i}" ${x.type!=='Consumable'?'disabled':''}>USE</button></div>`).join('')}</div>`:'<p class="empty-state">Your pack is empty. Search the frontier and dungeon chambers for supplies.</p>'}</div>`;

