function addItem(name,type='Consumable',qty=1){const item=state.inventory.find(x=>x.name===name);if(item)item.qty+=qty;else state.inventory.push({name,type,qty})}
function useItem(index){const item=state.inventory[index];if(!item||item.type!=='Consumable')return;if(item.name==='Field Ration'){state.hp=Math.min(maxHp(),state.hp+Math.floor(maxHp()*.3));state.mp=Math.min(maxMp(),state.mp+8)}else{state.hp=Math.min(maxHp(),state.hp+Math.floor(maxHp()*.55));state.mp=Math.min(maxMp(),state.mp+Math.floor(maxMp()*.35))}item.qty--;if(item.qty<=0)state.inventory.splice(index,1);showToast(`${item.name} used.`,'good');updateHud();openPanel('inventory');save()}
function rest(){const cost=state.roomType==='entrance'?0:10;if(state.currency<cost){showToast(`Resting here costs ${cost} essence.`,'warn');return}state.currency-=cost;state.hp=maxHp();state.mp=maxMp();state.day++;if(state.guild)state.currency+=10;setScene(['You take shelter while the world turns at its own pace.','Your wounds close and your mana returns. The frontier is still waiting.']);log('[REST] Vitals restored.','good');updateHud();renderChoices();save()}
function inspectRunes(){const lore=pick(['The runes describe a gate that grows stronger with every descent.','A phrase repeats in the stone: the shadow remembers its name.','The gate’s pulse follows your heartbeat. Somewhere below, something answers.']);setScene([lore,'The marks shift as you watch. The system records the pattern in your memory.']);state.history++;renderChoices();save()}
function explore(){state.day++;state.history++;const roll=Math.random();if(roll<.3){const amount=12+state.level*5;state.currency+=amount;setScene([`You search the broken structures and uncover <strong>${amount} essence</strong> in a sealed cache.`,`A faint gate hums in the distance. The Ashen Frontier has more secrets.`]);log(`[EXPLORE] Recovered ${amount} essence.`,'good')}else if(roll<.55){addItem(pick(['Field Ration','Minor Elixir']));setScene(['Among the gray rubble, you find a sealed supply case.','Its contents are still intact.']);log('[EXPLORE] Supplies recovered.','good')}else if(roll<.82){setScene(['A rift tears across the air. A hostile creature lunges from the breach.','There is no time to retreat.']);startCombat()}else{grantXp(10+state.level*3);setScene(['You follow a trail of violet residue to an old waystone.','Its energy steadies your resolve.']);}updateHud();renderChoices();save()}
function enterDungeon(){state.room=0;state.roomType='entrance';state.location='The Hollow Gate';state.history++;setScene(['The gate accepts your presence. Its interior unfolds into a chamber that could not fit inside the ruin.','A passage descends into the dark. Your first step is the only one that matters.']);log('[GATE] Dungeon instance entered.','info');updateHud();renderChoices();save()}
function advanceRoom(){state.room++;state.roomType='combat';state.location=`The Hollow Gate · Chamber ${state.room}`;state.history++;const names=['Grave Hound','Rift Stalker','Hollow Knight','Ash Wraith','Gatekeeper'];setScene([`Chamber ${state.room} opens around you. ${pick(['The stone sweats black water.','Pale motes drift against the wind.','A low vibration rattles your teeth.','The walls flex like something breathing.'])}`,`A <strong>${pick(names)}</strong> blocks the way. Its presence is stronger than the last.`]);startCombat();updateHud();renderChoices();save()}
