function combatAction(action){const e=state.combat;if(!e)return;let damage=0;if(action==='flee'){if(Math.random()<.65){state.combat=null;state.roomType=state.room?'cleared':'entrance';setScene(['You evade the creature and retreat through the breach.','For now, the fight is over.']);log('[COMBAT] Successful retreat.','info');renderChoices();save();return}log('[COMBAT] The escape route collapses.','warn')}else if(action==='guard'){e.guard=true;setScene([`You brace against <strong>${esc(e.name)}</strong>.`,`The next incoming blow will be reduced.`])}else{if(action==='skill'&&state.mp<8){showToast('Not enough MP.','warn');return}if(action==='skill')state.mp-=8;const stat=action==='skill'?state.stats.Intelligence:state.stats.Strength;damage=Math.max(4,Math.floor((stat*1.7+state.level*3+Math.random()*9)*(action==='skill'?1.85:1)));if(state.skills.includes('Umbral Strike')&&action==='skill')damage=Math.floor(damage*1.25);if(state.army.length)damage+=Math.min(state.army.length*3,15);if(state.deployed)damage+=5;e.hp=Math.max(0,e.hp-damage);setScene([`You deal <strong>${damage}</strong> damage to ${esc(e.name)}.`,`<strong>${esc(e.name)}</strong> · ${e.hp} / ${e.maxHp} HP`]);log(`[COMBAT] ${action==='skill'?'Technique':'Strike'} dealt ${damage} damage.`,'good')}
if(e.hp<=0){winCombat(e);return}const dodge=state.skills.includes('Rift Step')&&Math.random()<.22, incoming=Math.max(1,e.attack+Math.floor(Math.random()*5)-Math.floor(state.stats.Agility/4));if(dodge){setScene([`You evade ${esc(e.name)}’s counterattack with Rift Step.`,`The creature staggers, exposing its shadow.`]);log('[COMBAT] Rift Step evaded the attack.','good')}else{const taken=e.guard?Math.max(1,Math.floor(incoming*.35)):incoming;e.guard=false;state.hp=Math.max(0,state.hp-taken);setScene([`<strong>${esc(e.name)}</strong> counters for ${taken} damage.`,`You have ${state.hp} / ${maxHp()} HP remaining.`]);log(`[COMBAT] Took ${taken} damage.`,'warn')}
if(state.hp<=0){state.hp=Math.ceil(maxHp()*.45);state.mp=Math.ceil(maxMp()*.35);state.currency=Math.max(0,state.currency-15);state.combat=null;state.roomType=state.room?'cleared':'entrance';state.location=state.room?'The Hollow Gate · Safe chamber':'The Ashen Frontier';setScene(['Your vision fades. The system pulls you to safety before the final blow.','You recover with reduced vitals; some essence was lost. The gate remains.']);showToast('Defeated. Returned to safety.','warn');log('[COMBAT] Emergency recovery triggered.','warn')}
updateHud();renderChoices();save()}
function winCombat(enemy){state.combat=null;state.roomType='cleared';state.hp=Math.min(maxHp(),state.hp+Math.floor(maxHp()*.08));const xp=25+enemy.level*14+state.room*7,essence=12+enemy.level*7;state.currency+=essence;grantXp(xp);progressQuest('room');progressQuest('defeat');state.pendingExtraction={name:enemy.name,rank:enemy.level>8?'A':enemy.level>4?'B':'C',power:enemy.level*4+10,chance:Math.min(90,55+state.stats.Perception*2+state.stats.Luck)};setScene([`<strong>${esc(enemy.name)}</strong> falls. The chamber’s pressure releases, leaving only drifting shadow.`,`Victory yields ${xp} experience and ${essence} essence. The remnant can be claimed—or released.`]);log(`[VICTORY] ${enemy.name} defeated · +${xp} XP · +${essence} essence.`,'good');updateHud();renderChoices();save()}
function extractShadow(){const rem=state.pendingExtraction;if(!rem)return;if(state.army.length>=99){showToast('Your legion has reached its current capacity.','warn');return}if(Math.random()*100<rem.chance){state.army.push({name:rem.name,rank:rem.rank,power:rem.power,loyalty:75});log(`[ARISE] ${rem.name} joined the shadow legion.`,'good');showToast(`${rem.name} has arisen.`,'good');progressQuest('shadow')}else{log(`[ARISE] ${rem.name} resisted the binding.`,'warn');showToast('The shadow resisted.','warn')}state.pendingExtraction=null;state.roomType='cleared';setScene(['The remaining darkness is drawn into your hand.','The gate’s silence returns. What lies deeper is still unknown.']);updateHud();renderChoices();save()}

