function extractShadow(){const rem=state.pendingExtraction;if(!rem)return;if(state.army.length>=99){showToast('Your legion has reached its current capacity.','warn');return}if(Math.random()*100<rem.chance){state.army.push({name:rem.name,rank:rem.rank,power:rem.power,loyalty:75});log(`[ARISE] ${rem.name} joined the shadow legion.`,'good');showToast(`${rem.name} has arisen.`,'good');progressQuest('shadow')}else{log(`[ARISE] ${rem.name} resisted the binding.`,'warn');showToast('The shadow resisted.','warn')}state.pendingExtraction=null;state.roomType='cleared';setScene(['The remaining darkness is drawn into your hand.','The gate’s silence returns. What lies deeper is still unknown.']);updateHud();renderChoices();save()}
function progressQuest(kind){let changed=false;for(const q of state.quests){if(q.progress<q.target&&q.kind===kind){q.progress++;changed=true;if(q.progress>=q.target){q.active=false;state.currency+=q.reward;log(`[QUEST COMPLETE] ${q.title} · +${q.reward} essence.`,'good');showToast(`Directive complete: ${q.title}`,'good')}}}if(changed)updateHud()}
function newQuest(){const templates=[['Frontier Survey','Explore the world beyond the gate.',3,'explore',45],['Clear the Rift','Defeat foes within any gate.',3,'defeat',60],['Raise a Legion','Bind one shadow to your army.',1,'shadow',80]];const data=pick(templates);if(state.quests.some(q=>q.title===data[0])){showToast('That directive is already in your log.');return}state.quests.push({id:`side-${Date.now()}`,title:data[0],description:data[1],target:data[2],progress:0,kind:data[3],reward:data[4],active:true});log(`[QUEST] New directive: ${data[0]}.`,'good');updateHud();openPanel('quests');save()}
function adminAction(action){if(action==='reset'){modal('Reset local run?','This permanently deletes this game’s save from this browser.',[{label:'DELETE RUN',action:()=>{localStorage.removeItem(SAVE_KEY);location.reload()}},{label:'CANCEL',action:()=>{}}]);return}if(action==='heal'){state.hp=maxHp();state.mp=maxMp();showToast('Vitals restored.','good')}if(action==='essence'){state.currency+=100;showToast('100 essence granted.','good')}if(action==='xp'){grantXp(250);showToast('Experience granted.','good')}updateHud();openPanel('admin');save()}
